<?php if(cart_items($store)===[]):?><section class="section"><div class="container empty"><h1>Your basket is empty.</h1><a class="button primary" href="/products">Browse products</a></div></section><?php else:?><section class="page-hero"><div class="container narrow"><p class="eyebrow">Checkout</p><h1>Your details</h1><p>Enter your details, then continue to Stripe's secure hosted payment page.</p></div></section><section class="section"><div class="container checkout-grid"><div class="panel"><form class="form-grid" method="post" action="/checkout" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if(isset($formErrors['form'])):?><p class="error" role="alert"><?=e($formErrors['form'])?></p><?php endif;?><div class="field"><label for="name">Name</label><input id="name" name="name" type="text" autocomplete="name" maxlength="100" required value="<?=e((string)($formData['name']??''))?>"><?php if(isset($formErrors['name'])):?><span class="error"><?=e($formErrors['name'])?></span><?php endif;?></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required value="<?=e((string)($formData['email']??''))?>"><?php if(isset($formErrors['email'])):?><span class="error"><?=e($formErrors['email'])?></span><?php endif;?></div><button class="button primary" type="submit">Continue to secure payment</button></form></div><aside class="panel"><h2>Order summary</h2><?php foreach(cart_items($store) as $item):?><p><?=e($item['product']['name'])?> × <?=e((string)$item['quantity'])?><br><strong><?=e(money((int)$item['line_total'],$store))?></strong></p><?php endforeach;?><div class="total-row"><span>Total</span><span><?=e(money(cart_total($store),$store))?></span></div><p class="muted small-note"><?=e((string)$store['checkout']['shipping_label'])?> — <?=e((string)$store['checkout']['shipping_description'])?></p></aside></div></section><?php endif;?>
